321	    @Test
322	    void concurrentFinalFailAndApprovals_neverReleasesRejectedBatch() throws Exception {
323	        String batchKey = "BK-RACE-FAIL-" + unique();
324	        createBatch(batchKey, List.of("t1", "t2"), 201);
325	        submitTest(batchKey, testReq("TK-1", "t1", "PASS", "insp-a"), null, null, 201);
326	
327	        // 同时：最后一项 FAIL、QUALITY 批准、OPERATIONS 批准。行锁按提交顺序串行。
328	        List<Future<Integer>> results = runConcurrent(
329	                () -> callStatus(post("/api/batches/" + batchKey + "/tests")
330	                        .contentType(MediaType.APPLICATION_JSON)
331	                        .content(testReq("TK-2", "t2", "FAIL", "insp-b"))),
332	                () -> callStatus(post("/api/batches/" + batchKey + "/approvals")
333	                        .header("X-Actor-Id", "qa").header("X-Approval-Role", "QUALITY")
334	                        .contentType(MediaType.APPLICATION_JSON).content("{\"commandKey\":\"CA1\"}")),
335	                () -> callStatus(post("/api/batches/" + batchKey + "/approvals")
336	                        .header("X-Actor-Id", "ops").header("X-Approval-Role", "OPERATIONS")
337	                        .contentType(MediaType.APPLICATION_JSON).content("{\"commandKey\":\"CA2\"}"))
338	        );
339	
340	        // 起始为 QUARANTINED：任一批准先获锁都因检验未全部 PASS 返回 422；
341	        // FAIL 提交后批次 REJECTED，后续批准一律 409。绝无失败批次被放行。
342	        assertEquals("REJECTED", currentStatus(batchKey));
343	        Integer approvals = jdbc.queryForObject(
344	                "SELECT COUNT(*) FROM approval WHERE batch_key = ?", Integer.class, batchKey);
345	        assertEquals(0, approvals, "存在 FAIL 的批次不得留下任何批准");
346	        assertEquals(201, results.get(0).get(30, TimeUnit.SECONDS));
347	        assertTrue(results.get(1).get(30, TimeUnit.SECONDS) == 409
348	                || results.get(1).get(30, TimeUnit.SECONDS) == 422);
349	        assertTrue(results.get(2).get(30, TimeUnit.SECONDS) == 409
350	                || results.get(2).get(30, TimeUnit.SECONDS) == 422);
351	    }
