471	        // 同一检验项换 testKey 重复提交 → 409
472	        submitTest(batchKey, testReq("TK-2", "t1", "PASS", "i"), null, null, 409);
473	        submitTest(batchKey, testReq("TK-3", "t2", "PASS", "i"), null, null, 201);
474	
475	        MvcResult result = mockMvc.perform(get("/api/batches/" + batchKey + "/history"))
476	                .andExpect(status().isOk()).andReturn();
477	        JsonNode node = objectMapper.readTree(result.getResponse().getContentAsString());
478	        assertEquals("QUARANTINED", node.path("tests").get(0).path("batchStatus").asText(),
479	                "第一条 PASS 时仍在隔离");
480	        assertEquals("PENDING_RELEASE", node.path("tests").get(1).path("batchStatus").asText(),
481	                "最后一条 PASS 后进入待放行");
482	    }
483	
484	    @Test
485	    void failTestHistory_snapshotStatusRejected() throws Exception {
486	        String batchKey = "BK-FAIL-SNAP-" + unique();
487	        createBatch(batchKey, List.of("t1"), 201);
488	        submitTest(batchKey, testReq("TK-1", "t1", "FAIL", "i"), null, null, 201);
489	        MvcResult result = mockMvc.perform(get("/api/batches/" + batchKey + "/history"))
490	                .andExpect(status().isOk()).andReturn();
491	        JsonNode node = objectMapper.readTree(result.getResponse().getContentAsString());
492	        assertEquals("REJECTED", node.path("tests").get(0).path("batchStatus").asText());
493	        assertEquals("REJECTED", node.path("batch").path("status").asText());
494	    }
495	
496	    // ---------- helpers ----------
497	
498	    private record CreateCmd(String commandKey, String batchKey, String productCode, String batchNo,
499	                             Instant producedAt, List<String> requiredTests) {
500	    }
501	
502	    private String unique() {
503	        return UUID.randomUUID().toString().substring(0, 8);
504	    }
505	
506	    private String createBody(String batchKey, List<String> items) throws Exception {
507	        return objectMapper.writeValueAsString(new CreateCmd("CK-1", batchKey, "PROD-1", "LOT-1",
508	                Instant.parse("2026-01-02T03:04:05Z"), items));
509	    }
510	
511	    private void createBatch(String batchKey, List<String> items, int expectedStatus) throws Exception {
512	        mockMvc.perform(post("/api/batches")
513	                        .contentType(MediaType.APPLICATION_JSON).content(createBody(batchKey, items)))
514	                .andExpect(status().is(expectedStatus));
515	    }
516	
517	    private String testReq(String testKey, String item, String result, String inspector) throws Exception {
518	        return objectMapper.writeValueAsString(new TestCmd("CK-T-" + unique(), testKey, item, result, inspector));
519	    }
520	
