540	
541	    private void recall(String batchKey, String actor, String reason, String commandKey, int expected)
542	            throws Exception {
543	        mockMvc.perform(post("/api/batches/" + batchKey + "/recall")
544	                        .header("X-Actor-Id", actor)
545	                        .contentType(MediaType.APPLICATION_JSON)
546	                        .content("{\"commandKey\":\"" + commandKey + "\",\"reason\":\"" + reason + "\"}"))
547	                .andExpect(status().is(expected));
