    // ---------- 幂等：同参重放、异参 409、十进制按值 ----------

    @Test
    void requestId_replaySameParams_changedParamsConflict_decimalsByValue() throws Exception {
        String batchKey = "BK-PP-IDEM-" + unique();
        createBatch(batchKey, List.of("t1"), 201);

